#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json
from decimal import Decimal, ROUND_HALF_UP
from datetime import date, datetime, timedelta, timezone
import xml.etree.ElementTree as ET

KG = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
      'oz': Decimal('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
MONTHS = {m: i + 1 for i, m in enumerate(
    'jan feb mar apr may jun jul aug sep oct nov dec'.split())}


def read_bytes(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    m = re.search(rb'^#\s*charset\s*:\s*([A-Za-z0-9_.:-]+)', b[:4096], re.M)
    if m:
        try:
            return b.decode(m.group(1).decode('ascii'))
        except (LookupError, UnicodeDecodeError):
            pass
    try:
        return b.decode('utf-8')
    except UnicodeDecodeError:
        return b.decode('cp1252', errors='replace')


def sh_num(s):
    m = re.search(r'(?i)SH\D*(\d+)', s or '')
    return int(m.group(1)) if m else None


def norm_status(s):
    s = re.sub(r'[\s_\-]+', '_', (s or '').strip().lower())
    return s


def counted(s):
    return s in ('delivered', 'delivered_late')


def to_dec(s, decimal_comma=False):
    s = s.strip()
    if decimal_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


UNIT_RE = re.compile(r'(?i)^\s*([-+0-9.,]+)\s*(kg|g|lb|lbs|oz)\s*$')


def weight_kg(text, unit, decimal_comma=False):
    m = UNIT_RE.match(text)
    if m:
        text, unit = m.group(1), m.group(2).lower()
    unit = (unit or 'kg').lower()
    if unit == 'lbs':
        unit = 'lb'
    return to_dec(text, decimal_comma) * KG[unit]


DT_RE = re.compile(r'^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|z|[+-]\d\d(?::?\d\d)?)?$')


def month_of(value, form='iso'):
    v = value.strip()
    m = DT_RE.match(v)
    if m:
        y, mo, d, hh, mi = map(int, m.groups()[:5])
        ss = int(m.group(6) or 0)
        dt = datetime(y, mo, d, hh, mi, ss)
        tz = m.group(7)
        if tz and tz not in 'Zz':
            sign = 1 if tz[0] == '+' else -1
            digs = tz[1:].replace(':', '')
            off = timedelta(hours=int(digs[:2]), minutes=int(digs[2:4] or 0))
            dt = dt - sign * off
        return '%04d-%02d' % (dt.year, dt.month)
    f = re.sub(r'\s+', '', form or 'iso').upper()
    if f == 'SERIAL':
        d = date(1899, 12, 30) + timedelta(days=int(float(v)))
        return '%04d-%02d' % (d.year, d.month)
    m = re.match(r'^(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})$', v)
    if m:
        return '%04d-%02d' % (int(m.group(3)), MONTHS[m.group(2).lower()])
    p = [int(x) for x in re.findall(r'\d+', v)]
    if len(p) < 3:
        raise ValueError(v)
    if f in ('ISO', 'YMD', 'YYYY-MM-DD'):
        y, mo = p[0], p[1]
    elif f in ('DMY', 'DD/MM/YYYY', 'DD.MM.YYYY', 'DD-MM-YYYY'):
        y, mo = p[2], p[1]
    elif f in ('MM/DD/YYYY', 'MDY'):
        y, mo = p[2], p[0]
    else:
        raise ValueError(f)
    return '%04d-%02d' % (y, mo)


def doy_month(y, n):
    d = date(y, 1, 1) + timedelta(days=n - 1)
    return '%04d-%02d' % (d.year, d.month)


# record: (num, type, month, kg, status)  type in new/corr/void
def rec(num, typ, month, kg, status):
    return (num, typ, month, kg, norm_status(status))


def void_rec(num):
    return (num, 'void', None, None, None)


# ---------- delimited ----------
COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status', 'note'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
}
DELIM = {'east': ',', 'lakeside': ',', 'river': '\t', 'west': ';', 'harbor': '|'}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY', 'harbor': 'iso'}
BASE_UNIT = {'east': 'kg', 'lakeside': 'kg', 'river': 'kg', 'west': 'kg', 'harbor': 'kg'}
WCOL = {'east': 'gross', 'lakeside': 'gross_kg', 'river': 'weight', 'west': 'weight', 'harbor': 'weight'}
TYPES = {'N': 'new', 'NEW': 'new', '': 'new', 'C': 'corr', 'COR': 'corr', 'CORR': 'corr',
         'V': 'void', 'VOID': 'void'}


def colname_ok(depot, name):
    n = name.strip().lower()
    if n in COLS[depot]:
        return True
    return bool(re.match(r'^(gross|net|weight)(_(kg|g|lb|oz))?$', n))


def parse_delimited(depot, text):
    delim = DELIM[depot]
    quoted = (delim == ',')
    lines = text.split('\n')
    seq = None
    out = []
    dirs = {}
    header = None
    i = 0
    while i < len(lines):
        line = lines[i].rstrip('\r')
        i += 1
        if line.startswith('#'):
            m = re.match(r'^#\s*seq\s*[:=]\s*(\d+)', line) or re.search(r'\bseq=(\d+)', line)
            if m and line.startswith('#harbor') or (m and re.match(r'^#\s*seq\s*:', line)):
                seq = int(m.group(1))
            m = re.match(r'^#\s*([^:=]+?)\s*:\s*(.*?)\s*$', line)
            if m:
                dirs[re.sub(r'\s+', ' ', m.group(1).strip().lower())] = m.group(2)
            continue
        if line.strip() == '':
            continue
        if quoted:
            while line.count('"') % 2 == 1 and i < len(lines):
                line += '\n' + lines[i].rstrip('\r')
                i += 1
            row = next(csv.reader(io.StringIO(line, newline='')))
        else:
            row = line.split(delim)
        if all(colname_ok(depot, c) for c in row):
            header = [c.strip().lower() for c in row]
            continue
        if header is None:
            continue
        r = parse_row(depot, header, row, dirs)
        if r:
            out.append(r)
    return seq, out


def parse_row(depot, header, row, dirs):
    row_unit = None
    wi = None
    for k, h in enumerate(header):
        if h == WCOL[depot] or re.match(r'^(gross|weight)(_(kg|g|lb|oz))?$', h):
            if depot == 'east' and not h.startswith('gross'):
                continue
            wi = k
    if len(row) == len(header) + 1 and wi is not None:
        # row carries its own unit, placed right after the weight column
        cand = row[wi + 1].strip().lower()
        if cand in KG or cand == 'lbs':
            row_unit = cand
            row = row[:wi + 1] + row[wi + 2:]
        else:
            for k, v in enumerate(row):
                if v.strip().lower() in KG:
                    row_unit = v.strip().lower()
                    row = row[:k] + row[k + 1:]
                    break
    if len(row) != len(header):
        return None
    d = dict(zip(header, row))
    idv = d.get('id') or d.get('ref')
    num = sh_num(idv)
    if num is None:
        return None
    t = d.get('type', d.get('kind', d.get('typ', d.get('t', d.get('rec', '')))))
    typ = TYPES.get(t.strip().upper())
    if typ is None:
        typ = 'corr' if t.strip().lower().startswith('corr') else 'new'
    if typ == 'void':
        return void_rec(num)
    # weight
    wkey = header[wi]
    unit = None
    mm = re.search(r'_(kg|g|lb|oz)$', wkey)
    if mm:
        unit = mm.group(1)
    elif row_unit:
        unit = row_unit
    else:
        u = dirs.get('unit') if depot == 'east' else dirs.get('weight unit')
        if u:
            unit = u.split()[0].lower()
        else:
            unit = BASE_UNIT[depot]
    kg = weight_kg(d[wkey], unit, depot == 'west')
    form = dirs.get('dates') or dirs.get('date format') or BASE_DATE[depot]
    if depot == 'west':
        form = 'DD.MM.YYYY'
    ship = d.get('shipped', d.get('date'))
    month = month_of(ship, form)
    status = d.get('status', d.get('state'))
    if depot == 'harbor':
        status = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
                  'RET': 'returned', 'HLD': 'held'}.get(status.strip().upper(), status)
    return rec(num, typ, month, kg, status)


# ---------- fixed width ----------
FW = {
    'FW1': dict(len=42, type=(9, 10), id=(0, 9), ship=(10, 17), w=(17, 25), st=(25, 26)),
    'FW2': dict(len=43, type=(0, 1), id=(1, 10), ship=(10, 18), w=(18, 26), st=(26, 27)),
    'FW3': dict(len=41, type=(16, 17), id=(0, 9), ship=(9, 16), w=(17, 24), st=(24, 25)),
}
STAT = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def parse_fixed(text):
    seq = None
    layout = None
    out = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if '\f' in line or line.strip() == '':
            continue
        if line.startswith('#'):
            m = re.match(r'^#LAYOUT\s+(\S+)', line)
            if m:
                layout = m.group(1)
            m = re.match(r'^#SEQ\s+(\d+)', line)
            if m:
                seq = int(m.group(1))
            continue
        name = layout
        for k, v in FW.items():
            if len(line) == v['len']:
                name = k
        if name not in FW or len(line) != FW[name]['len']:
            continue
        L = FW[name]
        g = lambda k: line[L[k][0]:L[k][1]]
        num = sh_num(g('id'))
        if num is None:
            continue
        typ = {'N': 'new', 'C': 'corr', 'V': 'void'}.get(g('type').strip())
        if typ is None:
            continue
        if typ == 'void':
            out.append(void_rec(num))
            continue
        w = Decimal(int(g('w')))
        s = g('ship')
        if name == 'FW1':
            kg = w * KG['g']
            month = doy_month(int(s[:4]), int(s[4:]))
        elif name == 'FW2':
            kg = w / 100
            month = '%s-%s' % (s[:4], s[4:6])
        else:
            kg = w / 10 * KG['lb']
            month = doy_month(int(s[:4]), int(s[4:]))
        out.append(rec(num, typ, month, kg, STAT.get(g('st').strip(), g('st'))))
    return seq, out


# ---------- XML ----------
def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = root.get('weight-unit')
    out = []
    for e in root.iter('shipment'):
        num = sh_num(e.get('id'))
        if num is None:
            continue
        t = (e.get('type') or 'new').lower()
        typ = {'new': 'new', 'correction': 'corr', 'void': 'void'}.get(t, 'new')
        if typ == 'void':
            out.append(void_rec(num))
            continue
        we = e.find('weight')
        unit = we.get('unit') or runit
        kg = weight_kg(we.text, unit)
        se = e.find('shipped')
        ship = e.get('shipped') if e.get('shipped') else se.text
        month = month_of(ship)
        out.append(rec(num, typ, month, kg, e.findtext('status')))
    return seq, out


# ---------- JSON lines ----------
def parse_jsonl(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if 'meta' in o and 'id' not in o:
                if o['meta'].get('seq') is not None:
                    seq = int(o['meta']['seq'])
                continue
            num = sh_num(str(o.get('id')))
            if num is None:
                continue
            typ = {'new': 'new', 'amend': 'corr', 'void': 'void'}.get(o.get('kind', 'new'), 'new')
            if typ == 'void':
                out.append(void_rec(num))
                continue
            wk = [k for k in o if re.match(r'^weight_(kg|g|lb|oz)$', k)][0]
            kg = weight_kg(str(o[wk]), wk.split('_')[1])
            out.append(rec(num, typ, month_of(o['shipped_at']), kg, o.get('status')))
    return seq, out


def parse_file(depot, path):
    b = read_bytes(path)
    if depot == 'central' or b.lstrip()[:5] == b'<?xml' or b.lstrip()[:1] == b'<':
        return parse_xml(b)
    text = decode(b)
    if depot == 'south':
        return parse_fixed(text)
    if depot == 'north':
        return parse_jsonl(text)
    return parse_delimited(depot, text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        seq, recs = parse_file(depot, p)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, recs))
    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        cur = {}
        for seq, name, recs in sorted(files, key=lambda x: (x[0], x[1])):
            for r in recs:
                num, typ = r[0], r[1]
                if typ == 'new':
                    if num in cur:
                        resends += 1
                    else:
                        cur[num] = r
                elif typ == 'corr':
                    cur[num] = r
                    corrections += 1
                else:
                    cur.pop(num, None)
                    corrections += 1
        current[depot] = cur
    rank = {d: i for i, d in enumerate(ORDER)}
    owners = {}
    for depot in sorted(current, key=lambda d: rank.get(d, 99)):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    depots = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    for num, ds in owners.items():
        d = ds[0]
        r = current[d][num]
        if not counted(r[4]):
            continue
        depots[d][0] += 1
        depots[d][1] += r[3]
        m = months.setdefault(r[2], [0, Decimal(0)])
        m[0] += 1
        m[1] += r[3]
    q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': q(v[1])} for d, v in depots.items()},
        'months': {m: {'shipments': v[0], 'total_kg': q(v[1])} for m, v in sorted(months.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(res, f, indent=2)


main()
